class FakeServer:
    def __init__(self):
        self.version = 1

    def get(self, url, headers):
        etag = f'"v{self.version}"'
        if headers.get("If-None-Match") == etag:
            return 304, {"ETag": etag}, b""
        body = f'{{"name": "Ada", "version": {self.version}}}'.encode()
        return 200, {"ETag": etag}, body


class CachingClient:
    def __init__(self, server):
        self.server = server
        self.cache = {}

    def get(self, url):
        return self.server.get(url, {})[2]
